        if status != "open":
            return _fail(
                f"only open bills can be voided: bill_id={bill_id} status={status}"
            )
        connection.execute(
            "UPDATE bills SET status = 'voided' WHERE id = ?", (bill_id,)
        )
        connection.commit()
    finally:
        connection.close()

    print(
        json.dumps(
            {"bill_id": bill_id, "status": "voided"},
            ensure_ascii=False,
            separators=(",", ":"),
        )
    )
    return 0

